(function(){
'use strict';
const C=window.THCore,M=window.THExperienceMarkup;if(!C||!M||!window.TECH_HORIZON)return;
const $=s=>document.querySelector(s),draft=C.storage.get('th-draft',null),D=C.storage.get('th-preview',false)&&draft&&!C.validate(draft).length?draft:window.TECH_HORIZON;
if(document.body.dataset.page==='catalog'){
 const routes=new Set(window.TH_STATIC_ROUTES||[]),url=a=>routes.has(a.id)?'bai-viet/'+a.id+'.html':'doc-bai.html?id='+encodeURIComponent(a.id),params=new URLSearchParams(location.search),query=$('#catalog-query'),category=$('#catalog-category'),sort=$('#catalog-sort');
 let view=params.get('view')==='list'?'list':'grid';function applyView(){const list=view==='list';$('#catalog-grid').classList.toggle('catalog-list',list);document.querySelectorAll('[data-catalog-view]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.catalogView===view)));}document.querySelectorAll('[data-catalog-view]').forEach(button=>button.addEventListener('click',()=>{view=button.dataset.catalogView;applyView();render();}));applyView();
 query.value=(params.get('q')||'').slice(0,100);category.value=D.categories.some(c=>c.id===params.get('category'))?params.get('category'):'all';sort.value=['newest','oldest','shortest'].includes(params.get('sort'))?params.get('sort'):'newest';
 function render(updateUrl=true){const list=C.filter(D.articles,{query:query.value,category:category.value,sort:sort.value});$('#catalog-grid').innerHTML=list.map(a=>M.catalogCard(a,D,C,url(a))).join('');const raw=C.storage.get('th-saved',[]),saved=Array.isArray(raw)?raw:[];document.querySelectorAll('#catalog-grid [data-save]').forEach(b=>{const on=saved.includes(b.dataset.save);b.setAttribute('aria-pressed',String(on));b.setAttribute('aria-label',(on?'Bỏ lưu bài: ':'Lưu bài: ')+(D.articles.find(a=>a.id===b.dataset.save)?.title||''));});$('#catalog-status').textContent=list.length+' / '+D.articles.length+' cẩm nang'+(query.value?' cho “'+query.value+'”':'');$('#catalog-empty').hidden=list.length>0;if(updateUrl)try{const u=new URL(location.href);for(const[k,v,empty]of [['q',query.value,''],['category',category.value,'all'],['sort',sort.value,'newest'],['view',view,'grid']]){if(v===empty)u.searchParams.delete(k);else u.searchParams.set(k,v);}history.replaceState(null,'',u);}catch{}}
 function reset(){query.value='';category.value='all';sort.value='newest';render();query.focus();}
 $('#catalog-form').addEventListener('submit',e=>{e.preventDefault();render();});query.addEventListener('input',()=>render());category.addEventListener('change',()=>render());sort.addEventListener('change',()=>render());$('#catalog-reset').addEventListener('click',reset);$('#catalog-show-all').addEventListener('click',reset);window.addEventListener('storage',e=>{if(e.key==='th-saved')render(false);});render(false);
}
const articleId=document.body.dataset.page==='article'?document.body.dataset.article:document.body.dataset.page==='dynamic-article'?new URLSearchParams(location.search).get('id'):null,article=D.articles.find(a=>a.id===articleId),Editorial=window.THEditorial;
if(article&&Editorial){
 if(document.body.dataset.page==='dynamic-article'){const main=document.querySelector('#main');if(main){main.querySelector('.breadcrumb')?.remove();main.insertAdjacentHTML('beforebegin',Editorial.pageChrome('bai-viet/'+article.id+'.html',D,C,''));}}
 const old=document.querySelector('.article-sources');if(old&&!old.classList.contains('source-panel'))old.outerHTML=Editorial.sources(article,D,C);
 const tools=document.querySelector('.reader-tools>div:last-child');if(tools&&!tools.querySelector('a[href="#nguon-tham-khao"]'))tools.insertAdjacentHTML('beforeend','<a class="reader-control" href="#nguon-tham-khao">Xem nguồn ↘</a>');
 document.querySelectorAll('[data-download-reading]').forEach(button=>{button.hidden=false;button.addEventListener('click',()=>{const blob=new Blob([Editorial.readingText(article,D,C)],{type:'text/plain;charset=utf-8'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='Tech_Horizon_'+article.id+'.txt';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),10000);});});
}
document.querySelectorAll('.desktop-nav a,.mobile-menu a,.header-library').forEach(link=>{try{const url=new URL(link.href,location.href);if(!url.hash&&url.pathname===location.pathname)link.setAttribute('aria-current','page');}catch{}});
})();
